let coverageProgramId=null,coverageDays=7;
function coverageSql(p,days){return `-- Dummy coverage output only; this does not evaluate source data.
-- Saved incentive: ${p.name.replace(/[\r\n]/g,' ')}
-- Selected history: last ${days} days.
SELECT
  1000 AS total_eligible_users,
  640 AS total_users_who_will_earn,
  128000 AS total_amount_earned;`}
function openCoverage(id){coverageProgramId=id;const p=programs.find(p=>p.id===id);if(!p?.id||programValidation(p)){toast('Complete and save the incentive configuration before checking coverage.');return}let sql='',error='';try{sql=coverageSql(p,coverageDays)}catch(e){error=e.message}const d=document.getElementById('fieldDialog');d.classList.add('details-dialog');d.innerHTML=`<div class="panel-head"><div><h2>Check coverage</h2><span class="quiet">${esc(p.name)}</span></div><button class="close" id="closeCoverage" aria-label="Close coverage">×</button></div><div class="dialogbody"><div class="group"><label class="label" for="coverageDays">Historical period ${info('Completed days before today. Uses the saved incentive configuration. Users are counted once across the window.')}</label><select id="coverageDays">${[7,14].map(n=>`<option value="${n}" ${n===coverageDays?'selected':''}>Last ${n} days</option>`).join('')}</select></div><p class="quiet">${esc(p.evaluation)} evaluation · Dummy coverage preview${['Weekly','Monthly'].includes(p.evaluation)?' · Includes partial evaluation periods':''}</p><div class="panel"><div class="panel-head"><h2>Dummy output</h2><span class="badge">Dummy values</span></div><div class="panel-body"><dl><dt>Total eligible users</dt><dd>1,000</dd><dt>Total users who will earn</dt><dd>640</dd><dt>Total amount earned</dt><dd>₹1,28,000</dd></dl><p class="quiet">Dummy values only. These totals are not calculated from the selected configuration or historical period.</p></div></div><div class="savebar"><label class="label" for="coverageSql">Sample query</label><button class="button" id="copyCoverage" ${error?'disabled':''}>Copy query</button></div>${error?`<div class="notice error" role="alert">${esc(error)}</div>`:`<textarea id="coverageSql" readonly spellcheck="false" style="min-height:300px;width:100%">${esc(sql)}</textarea>`}<p class="quiet">This sample query returns the dummy totals shown above. No database is connected.</p><span id="coverageCopyStatus" role="status"></span></div>`;if(!d.open)d.showModal();document.getElementById('closeCoverage').onclick=()=>d.close();document.getElementById('coverageDays').onchange=e=>{coverageDays=Number(e.target.value);openCoverage(id)};document.getElementById('copyCoverage').onclick=async()=>{try{await navigator.clipboard.writeText(sql);document.getElementById('coverageCopyStatus').textContent='Query copied.'}catch{const area=document.getElementById('coverageSql');area.focus();area.select();document.getElementById('coverageCopyStatus').textContent='Select and copy the query with your keyboard.'}}}
const beforeCoverageList=managerList;
managerList=function(){return beforeCoverageList().replace(/(<button class="link" data-edit-program="(\d+)">[^<]+<\/button>)/g,(_,button,id)=>button+` <button class="link" data-coverage="${id}">Check coverage</button>`)};
const beforeCoverageBinding=bindManager;
bindManager=function(){beforeCoverageBinding();document.querySelectorAll('[data-coverage]').forEach(b=>b.onclick=()=>openCoverage(Number(b.dataset.coverage)))};
const beforeCoverageSave=saveProgram;
saveProgram=function(status){const p=programEdit;const result=beforeCoverageSave(status);if(result)openCoverage(p.id);return result};
render();
